        openFileDialog.Filter = "Adressen-Datenbank (*.adb)|*.adb|Alle Dateien (*.*)|*.*";
        openFileDialog.InitialDirectory = "Environment.CurrentDirectory";
        openFileDialog.Title = "Open SQLite Database File";
        // 
        // saveFileDialog
        // 
        saveFileDialog.DefaultExt = "adb";
        saveFileDialog.Filter = "Adressen-Datenbank (*.adb)|*.adb|Alle Dateien (*.*)|*.*";
        // 
        // debounceTimer
        // 
        debounceTimer.Interval = 500;
        debounceTimer.Tick += DebounceTimer_Tick;
        // 
        // fileSysWatcher
        // 
        fileSysWatcher.EnableRaisingEvents = true;
        fileSysWatcher.IncludeSubdirectories = true;
        fileSysWatcher.NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite | NotifyFilters.CreationTime;
        fileSysWatcher.SynchronizingObject = this;
        fileSysWatcher.Changed += FileSystemWatcher_OnChanged;
        fileSysWatcher.Created += FileSystemWatcher_OnChanged;
        fileSysWatcher.Renamed += FileSystemWatcher_OnRenamed;
        // 
        // addressBSource
        // 
        addressBSource.CurrentChanged += AddressBindingSource_CurrentChanged;
        addressBSource.ListChanged += AddressBindingSource_ListChanged;
        // 
        // contactBSource
        // 
        contactBSource.CurrentChanged += ContactBindingSource_CurrentChanged;
        contactBSource.ListChanged += ContactBindingSource_ListChanged;
        // 
        // searchTimer
        // 
        searchTimer.Interval = 200;
        searchTimer.Tick += SearchTimer_Tick;
        // 
        // notifyIcon
        // 
        notifyIcon.ContextMenuStrip = trayMenu;
        notifyIcon.Icon = (Icon)resources.GetObject("notifyIcon.Icon");
        notifyIcon.Text = "Adressen & Kontakte";
        notifyIcon.MouseClick += NotifyIcon_MouseClick;
        // 
        // trayMenu
        // 
        trayMenu.Font = new Font("Segoe UI", 10F);
        trayMenu.Items.AddRange(new ToolStripItem[] { openTrayMenuItem, trayMenuSeparator, exitTrayMenuItem });
        trayMenu.Name = "trayMenu";
        trayMenu.Size = new Size(135, 58);
        trayMenu.Opened += TrayMenu_Opened;
        // 
        // openTrayMenuItem
        // 
        openTrayMenuItem.Name = "openTrayMenuItem";
        openTrayMenuItem.Size = new Size(134, 24);
        openTrayMenuItem.Text = "Anzeigen";
        openTrayMenuItem.Click += OpenTrayMenuItem_Click;
        // 
        // trayMenuSeparator
        // 
        trayMenuSeparator.Name = "trayMenuSeparator";
        trayMenuSeparator.Size = new Size(131, 6);
        // 
        // exitTrayMenuItem
        // 
        exitTrayMenuItem.Name = "exitTrayMenuItem";
        exitTrayMenuItem.Size = new Size(134, 24);
        exitTrayMenuItem.Text = "Beenden";
        exitTrayMenuItem.Click += ExitTrayMenuItem_Click;
        // 
        // FrmAdressen
        // 
        AutoScaleDimensions = new SizeF(7F, 17F);
        AutoScaleMode = AutoScaleMode.Font;
        ClientSize = new Size(1237, 816);
        Controls.Add(splitContainer);
        Controls.Add(statusStrip);
        Controls.Add(toolStrip);
        Controls.Add(menuStrip);
        DoubleBuffered = true;
        Font = new Font("Segoe UI", 10F);
        Icon = (Icon)resources.GetObject("$this.Icon");
        MainMenuStrip = menuStrip;
        MinimumSize = new Size(932, 576);
        Name = "FrmAdressen";
        Opacity = 0D;
        Text = "Adressen & Kontakte";
        Activated += FrmAdressen_Activated;
        Deactivate += FrmAdressen_Deactivate;
        FormClosing += FrmAdressen_FormClosing;
        Load += FrmAdressen_Load;
        Shown += FrmAdressen_Shown;
        Resize += FrmAdressen_Resize;
        menuStrip.ResumeLayout(false);
        menuStrip.PerformLayout();
        toolStrip.ResumeLayout(false);
        toolStrip.PerformLayout();
        statusStrip.ResumeLayout(false);
        statusStrip.PerformLayout();
